parameters.inputSchema:
={
  "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "properties": {
    "customer_name": {
      "type": "string",
      "description": "Explicit customer name from input message. Return 'Valued Client' if missing."
    },
    "company_name": {
      "type": "string",
      "description": "Explicit company name from input message. Return 'Not Provided' if missing."
    },
    "project_type": { 
      "type": "string",
      "description": "Short category e.g., AI Website Chatbot"
    },
    "estimated_budget": { 
      "type": "string",
      "description": "Budget strictly in INR (e.g., ₹2,50,000). Use user's budget if provided."
    },
    "estimated_timeline": { 
      "type": "string",
      "description": "Timeline strictly matching user's request (e.g., 4 Weeks)."
    },
    "proposal_title": { 
      "type": "string",
      "description": "Title strictly in UPPERCASE."
    },
    "proposal_summary": { 
      "type": "string",
      "description": "Executive summary of the proposal."
    },
    "recommended_solutions": { 
      "type": "string",
      "description": "Bullet-pointed list of solutions (e.g., • Feature 1\\n• Feature 2)."
    },
    "deliverables": { 
      "type": "string",
      "description": "Bullet-pointed list of deliverables with checkmarks (e.g., ✔ Deliverable 1\\n✔ Deliverable 2)."
    },
    "phased_roadmap": { 
      "type": "string",
      "description": "Phased implementation plan if budget mismatch exists."
    },
    "next_steps": { 
      "type": "string",
      "description": "Bullet-pointed next steps (e.g., • Step 1\\n• Step 2)."
    }
  },
  "required": [
    "customer_name",
    "company_name",
    "project_type",
    "estimated_budget",
    "estimated_timeline",
    "proposal_title",
    "proposal_summary",
    "recommended_solutions",
    "deliverables",
    "phased_roadmap",
    "next_steps"
  ]
}
